/**
 * PSE Stock Statistics Provider (trailing twelve months)
 *
 * Reads data/pse-stock-stats.json (generated by scripts/scrape-stock-stats.ts).
 *
 * This is the preferred fundamentals source, ahead of PseFundamentalsAdapter.
 * PSE EDGE publishes interim filings — 210 of 268 cover only the six months to
 * 30 June — so every ratio derived from them describes part of a year. The
 * run-rate extrapolation used previously was materially wrong: it put BDO's
 * P/E at 15.89 against a real trailing 7.56, because the filings' `eps` field
 * is not the half-year earnings figure it was taken to be. These are published
 * TTM values, so no extrapolation is involved.
 *
 * It also carries three inputs that existed nowhere else in the repo:
 * dividend yield (valuation's second sub-score), beta (risk's volatility
 * sub-score) and shares outstanding (a real P/B). Those lift the measurable
 * factor weight past researchEngine's 0.50 minimum, which is what previously
 * left every composite score unrated.
 *
 * Missing figures stay null and are never defaulted.
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface PseStockStats {
  symbol: string;
  eps: number | null;
  peRatio: number | null;
  forwardPe: number | null;
  dividendPerShare: number | null;
  /** Percent, e.g. 3.59 for 3.59%. */
  dividendYield: number | null;
  beta: number | null;
  sharesOutstanding: number | null;
  /** Absolute PHP. */
  marketCap: number | null;
  revenueTtm: number | null;
  netIncomeTtm: number | null;
  dayLow: number | null;
  dayHigh: number | null;
  scrapedAt: string | null;
}

type StatsMap = Record<string, PseStockStats>;

let cache: StatsMap | null = null;

function loadMap(): StatsMap {
  if (cache !== null) return cache;
  let loaded: StatsMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-stock-stats.json'), 'utf-8');
    loaded = JSON.parse(raw).results ?? {};
  } catch {
    // Not scraped yet — callers fall back to the EDGE filings.
  }
  cache = loaded;
  return loaded;
}

/** Published TTM statistics for a symbol, or null. */
export function getStockStats(symbol: string): PseStockStats | null {
  return loadMap()[symbol.toUpperCase()] ?? null;
}

/** Price-to-book from published shares outstanding and equity, or null. */
export function computePbRatio(symbol: string, price: number, totalEquityMillions: number | null): number | null {
  const stats = getStockStats(symbol);
  if (!stats?.sharesOutstanding || !totalEquityMillions || !price) return null;
  const bookPerShare = (totalEquityMillions * 1e6) / stats.sharesOutstanding;
  if (bookPerShare <= 0) return null;
  return Math.round((price / bookPerShare) * 100) / 100;
}

/** Formatted intraday range, e.g. "₱122.30 – ₱123.90", or null. */
export function getDayRange(symbol: string): { low: number; high: number } | null {
  const stats = getStockStats(symbol);
  if (stats?.dayLow == null || stats.dayHigh == null) return null;
  return { low: stats.dayLow, high: stats.dayHigh };
}

/** Clears the module cache so a regenerated file is picked up. */
export function reloadStockStats(): void {
  cache = null;
}
